"""Generate the protocol reference from runtime constants; --check rejects drift."""
import argparse
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / 'physics_server'))
import commands  # noqa: E402
import server  # noqa: E402
import world  # noqa: E402
import units  # noqa: E402


def render():
    lines = ['# Runtime reference', '',
             '<!-- Generated by tools/dev.py docs. Do not edit by hand. -->', '',
             f'Protocol version: **{server.PROTOCOL_VERSION}**. UDP port: **{server.DEFAULT_PORT}**.', '',
             'Every command requires `protocol: 2`. Packets use little-endian float32 values.', '',
             f'State kind: **{server.STATE_KIND}**; forecast kind: **{server.PREDICTION_KIND}** (9-float header).', '',
             f'Physical scenes: `{units.SYSTEM}`; migrated scenes: `{units.LEGACY}`. See [physical models](physical-model.md).', '',
             '| Record | Floats |', '|---|---:|',
             f'| State header | {server.HEADER_FLOATS} |',
             f'| Body | {server.BODY_FLOATS} |', f'| Event | {server.EVENT_FLOATS} |', '',
             f'At most {world.MAX_BODIES} bodies and {server.MAX_EVENTS_PER_PACKET} events fit in one packet.', '',
             '## Commands', '', '| Command | Fields / meaning |', '|---|---|']
    lines.extend(f'| `{key}` | {value} |' for key, value in commands.COMMANDS.items())
    lines += ['', '## Bodies', '', '| Key | ID | Default mass |', '|---|---:|---:|']
    lines.extend(f'| `{key}` | {value} | {world.DEFAULT_MASS[value]:g} |' for key, value in world.TYPE_KEYS.items())
    lines += ['', '## Events', '', '| Event | ID |', '|---|---:|']
    lines.extend(f'| `{key}` | {value} |' for key, value in vars(world).items() if key.startswith('EV_'))
    lines += ['', '## Scenarios', '', ', '.join(f'`{name}`' for name in world.SCENARIOS), '']
    return '\n'.join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    path = ROOT / 'docs/runtime-reference.md'
    expected = render()
    if args.check:
        if not path.exists() or path.read_text(encoding='utf-8') != expected:
            raise SystemExit('Runtime documentation is stale. Run python3 tools/dev.py docs.')
        print('Generated documentation is current.')
    else:
        path.write_text(expected, encoding='utf-8')


if __name__ == '__main__':
    main()
